<script lang="ts">
	import { onMount } from 'svelte';import { Check, Mail, Save, Send } from '@lucide/svelte';import { getEmailSettings,getEmailStatus,hasBmsSession,saveEmailSettings,testEmail,type EmailDeliveryStatus,type EmailSettings } from '$lib/services/bms-api';
	let settings=$state<EmailSettings>({enabled:false,host:'',port:25,security:'plain',username:'',passwordConfigured:false,senderAddress:'',senderName:'',recipients:[],categories:[],sendRecovery:true,reminderMinutes:60});let recipients=$state('');let password=$state('');let subject=$state('MaxiEMS email alert test');let body=$state('This is a MaxiEMS email-alert configuration test.');let status=$state<EmailDeliveryStatus[]>([]);let saving=$state(false);let notice=$state('');let error=$state('');
	const categories=[['missing-stale-data','Missing or stale BMS data'],['high-resistance','High internal resistance'],['high-temperature','High temperature'],['low-voltage','Low voltage'],['high-voltage','High voltage']];
	onMount(async()=>{if(!hasBmsSession())return;try{settings=await getEmailSettings();recipients=settings.recipients.join(', ');status=await getEmailStatus()}catch(e){error=message(e)}});
	function message(e:unknown){return e instanceof Error?e.message:'Request failed.'}function toggleCategory(key:string){settings.categories=settings.categories.includes(key)?settings.categories.filter(v=>v!==key):[...settings.categories,key]}
	function validate(){if(!settings.host.trim())return'SMTP host is required.';if(!Number.isInteger(Number(settings.port))||settings.port<1||settings.port>65535)return'SMTP port must be between 1 and 65535.';if(!settings.senderAddress.trim()||!recipients.trim())return'Sender address and at least one recipient are required.';if(!Number.isInteger(Number(settings.reminderMinutes))||settings.reminderMinutes<5)return'Reminder interval must be at least 5 minutes.';return''}
	async function save(){const v=validate();if(v){error=v;return false}saving=true;error='';try{if(hasBmsSession()){settings=await saveEmailSettings({...settings,host:settings.host.trim(),port:Number(settings.port),username:settings.username.trim(),senderAddress:settings.senderAddress.trim(),senderName:settings.senderName.trim(),recipients:recipients.split(',').map(v=>v.trim()).filter(Boolean),reminderMinutes:Number(settings.reminderMinutes)},password||undefined);recipients=settings.recipients.join(', ');password='';}notice='Email alert settings saved.';return true}catch(e){error=message(e);return false}finally{saving=false}}
	async function sendTest(){if(!(await save()))return;try{notice=hasBmsSession()?await testEmail(subject,body):'Test payload is ready; authenticate to send it.'}catch(e){error=message(e)}}
</script>
<section class="page"><div class="head"><div><h2><Mail size={23}/>Email Alerts</h2><p>Global SMTP relay settings and delivered BMS event categories.</p></div></div>{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}
	<section class="panel"><div class="enable"><div><strong>Enable email alerts</strong><span>Passwords stay on the appliance and are never returned.</span></div><button class:active={settings.enabled} class="switch" onclick={()=>settings.enabled=!settings.enabled}><i></i>{settings.enabled?'Enabled':'Disabled'}</button></div><div class="grid"><label>SMTP host<input bind:value={settings.host}/></label><label>Port<input type="number" min="1" max="65535" bind:value={settings.port}/></label><label>TLS mode<select bind:value={settings.security}><option value="plain">Plain (Mailpit)</option><option value="starttls">STARTTLS</option><option value="tls">TLS</option></select></label><label>Username (optional)<input bind:value={settings.username}/></label><label>Password {settings.passwordConfigured?'(configured; blank keeps it)':'(optional)'}<input type="password" bind:value={password}/></label><label>Sender address<input type="email" bind:value={settings.senderAddress}/></label><label>Sender display name<input bind:value={settings.senderName}/></label><label class="wide">Recipients<input bind:value={recipients} placeholder="operator@example.com, team@example.com"/><small>Separate addresses with commas.</small></label></div>
		<div class="section"><h3>Delivered BMS events</h3><p>Server-side snapshots use each string’s configured thresholds.</p><div class="checks">{#each categories as item}<label><input type="checkbox" checked={settings.categories.includes(item[0])} onchange={()=>toggleCategory(item[0])}/>{item[1]}</label>{/each}</div><div class="grid policy"><label>Persistent reminder (minutes)<input type="number" min="5" max="10080" bind:value={settings.reminderMinutes}/></label><label class="check"><input type="checkbox" bind:checked={settings.sendRecovery}/>Send recovery notifications</label></div></div>
		<div class="section"><h3>Test email</h3><p>Testing saves relay settings first; automatic alerts may remain disabled.</p><div class="grid"><label class="wide">Subject<input maxlength="200" bind:value={subject}/></label><label class="wide">Message<textarea rows="4" maxlength="10000" bind:value={body}></textarea></label></div></div>
		{#if status.length}<div class="section"><h3>Automatic delivery status</h3><ul>{#each status as item}<li><strong>{item.eventKey}</strong>: {item.lastDeliveryStatus.toLowerCase()} {item.active?'(active)':'(recovered)'} — {new Date(item.updatedAt).toLocaleString()}</li>{/each}</ul></div>{/if}
		<footer><button class="secondary" disabled={saving} onclick={sendTest}><Send size={16}/>Send test email</button><button class="primary" disabled={saving} onclick={save}><Save size={16}/>{saving?'Saving…':'Save settings'}</button></footer></section>
</section>
<style>
	.page{animation:in .18s ease}.head{margin-bottom:18px}.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 0;color:#718096;font-size:16px}.panel{overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.enable{display:flex;align-items:center;justify-content:space-between;padding:17px 19px;border-bottom:1px solid #edf0f4}.enable strong,.enable span{display:block}.enable strong{color:#31415c;font-weight:500}.enable span{margin-top:4px;color:#8792a4;font-size:12px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding:18px 19px}.grid label{display:grid;gap:6px;color:#536078;font-size:13px}.grid .wide{grid-column:1/-1}input,select,textarea{width:100%;padding:0 11px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit;font-size:14px}input,select{height:39px}textarea{padding-top:9px;resize:vertical}small{color:#8a95a7}.switch{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 9px;border:1px solid #d7dfeb;border-radius:16px;color:#77849a;background:#fff;cursor:pointer;font:inherit;font-size:12px}.switch i{width:8px;height:8px;border-radius:50%;background:#9ba6b5}.switch.active{border-color:#b9dfc9;color:#24764d;background:#f1fbf5}.switch.active i{background:#2eae68}.section{padding:18px 19px;border-top:1px solid #edf0f4}.section h3{margin:0;color:#31415c;font-size:16px;font-weight:500}.section>p{margin:5px 0 14px;color:#8792a4;font-size:13px}.section .grid{padding:0}.checks{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.checks label,.check{display:flex!important;align-items:center;gap:8px;color:#536078;font-size:13px}.checks input,.check input{width:16px;height:16px;accent-color:#1749ad}.policy{grid-template-columns:1fr 2fr;margin-top:16px}.notice,.error{margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{display:flex;align-items:center;gap:7px;color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}footer{display:flex;justify-content:flex-end;gap:8px;padding:12px 19px;border-top:1px solid #edf0f4}.primary,.secondary{display:inline-flex;align-items:center;gap:7px;height:38px;padding:0 14px;border-radius:8px;font:inherit;cursor:pointer}.primary{border:0;color:#fff;background:#1749ad}.secondary{border:1px solid #d7dfeb;color:#40516f;background:#fff}button:disabled{opacity:.55}@keyframes in{from{opacity:0;transform:translateY(4px)}}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.grid,.checks,.policy{grid-template-columns:1fr}.enable{align-items:flex-start;gap:12px}.grid .wide{grid-column:auto}footer{flex-direction:column}footer button{justify-content:center}}
</style>
